  const config = {
    apiKey: cleanText(env.FIREBASE_WEB_API_KEY, 300),
    authDomain: cleanText(env.FIREBASE_AUTH_DOMAIN, 300),
    databaseURL: cleanText(env.FIREBASE_DATABASE_URL, 500),
    projectId: cleanText(env.FIREBASE_PROJECT_ID, 200),
    storageBucket: cleanText(env.FIREBASE_STORAGE_BUCKET, 300),
    messagingSenderId: cleanText(env.FIREBASE_MESSAGING_SENDER_ID, 120),
    appId: cleanText(env.FIREBASE_APP_ID, 300),
    measurementId: cleanText(env.FIREBASE_MEASUREMENT_ID, 120)
  };
  const required = ['apiKey','authDomain','databaseURL','projectId','storageBucket','messagingSenderId','appId'];
  if (required.some(key => !config[key])) fail(503, 'STAGING_RUNTIME_CONFIG_REQUIRED', 'Staging Firebase web configuration is incomplete.');
  if (config.projectId === PROD_FIREBASE_WEB_CONFIG.projectId || config.authDomain === PROD_FIREBASE_WEB_CONFIG.authDomain || config.databaseURL === PROD_FIREBASE_WEB_CONFIG.databaseURL) {
    fail(503, 'STAGING_ISOLATION_VIOLATION', 'Staging runtime configuration points at a production Firebase resource.');
  }
