  if(!role||!expectedName)return null;
  const roster=await rosterResolvedStateServer(env);
  const rows=role==='agent'?(Array.isArray(roster?.employees?.entries)?roster.employees.entries:[]):(Array.isArray(roster?.teamLeaderDirectory?.entries)?roster.teamLeaderDirectory.entries:[]);
