    const name=normalizePersonName(raw.name||''),pod=cleanText(raw.pod||raw.team||'',80);
    if(!name||!pod||name.toLowerCase()!==expectedName.toLowerCase())continue;
    const employeeId=role==='agent'?cleanText(raw.employeeId||raw.id||'',120):'';
    const uid=legacyChatUid(role,name,employeeId,pod);
    matches.set(uid,{uid,name,role,pod,employeeId,active:true});
