  if (!/^https:\/\//i.test(dbUrl)) fail(503, 'CHAT_SERVER_CONFIG_REQUIRED', 'Workspace Messaging needs FIREBASE_DATABASE_URL.');
  const token = await getGoogleAccessToken(env);
  const response = await fetch(`${dbUrl}/${String(path || '').replace(/^\/+/, '')}.json`, { headers: { authorization: `Bearer ${token}`, accept: 'application/json' } });
