async function requirePremiumManagerApi(request, env) {
  const user = await requireFirebaseUser(request, env);
  const role = await firebaseAdminGet(env, `roles/${user.uid}`);
  const allowed = Boolean(role && typeof role === 'object' && role.active === true && String(role.role || '') === PREMIUM_MANAGER_ROLE && String(role.name || '') === PREMIUM_MANAGER_NAME && role.permissions && role.permissions[PREMIUM_MANAGER_PERMISSION] === true);
  if (!allowed) fail(403, 'PREMIUM_MANAGER_REQUIRED', 'This Firebase account is not authorized to manage the Premium entitlement.');
  return user;
}

