  const email = String(user.email || '').trim().toLowerCase();
  if (!email) fail(400, 'ADMIN_RECOVERY_EMAIL_REQUIRED', 'The signed-in Firebase account does not expose an email address.');
  const currentRole = await firebaseAdminGet(env, `roles/${user.uid}`).catch(() => null);
  const currentRoleName = normalizeRole(currentRole?.role);
  if (currentRole && currentRole.active === true && currentRoleName === 'admin') {
    return { ok:true, alreadyActive:true, candidate:null, authority:'owner-recovery-v1' };
  }
  // Owner Recovery may repair a missing Admin record or reactivate a previously
  // known Admin record. It must never convert a known Agent/TL/other workforce
  // identity into Admin authority just because that account was typed in the
  // Admin form.
