async function requireSecuritySession(request, env) {
  const token=String(request.headers.get('x-tt-security-session')||'');
  if(!token) fail(401,'SECURITY_SESSION_REQUIRED','Your TrinoTime security session expired. Sign in again.');
  return verifyCompactToken(env,token,'workforce-security');
}
