async function handleSecuritySessionValidate(request, env) {
  const actor=await requireSecuritySession(request,env);
  const current=await requireCurrentSecurityActor(env,actor);
  const role=credentialRole(actor.role),name=normalizePersonName(actor.name),pod=cleanText(current?.currentPod||actor.pod||'',80);
  if(!role||!name||!pod) fail(401,'SECURITY_SESSION_STALE','Your TrinoTime security session is no longer valid. Sign in again.');
  return {ok:true,role,name,pod,expiresAt:new Date(Number(actor.exp)||Date.now()).toISOString(),authority:'workforce-security-v1',release:RELEASE,fingerprint:BUILD_FINGERPRINT};
}
