  enforceRate(user.uid,'security-identity-request',12,60*60*1000);
  const body=await parseBody(request);
  const role=credentialRole(actor.role);
  const name=normalizePersonName(actor.name);
  const pod=cleanText(actor.pod||'',80);
  const generation=cleanText(body.generation||'',180);
  const identityKey=cleanText(body.identityKey||'',180);
  const previousUid=cleanText(body.previousUid||'',180);
  if(!role||!name||!pod||!generation||!identityKey)fail(400,'SECURITY_IDENTITY_REQUEST_INVALID','Identity migration request is incomplete.');
  const member=await findCredentialMember(env,role,name,pod);
  if(!member)fail(403,'SECURITY_MEMBER_NOT_FOUND','This workforce account is no longer active in the roster.');
  const loaded=await readAuthoritativeCredential(env,role,name,{migrateLegacy:true});
  if(!loaded.record||loaded.record.active===false)fail(403,'SECURITY_CREDENTIAL_UNAVAILABLE','Your workforce credential is unavailable.');
  const expectedGeneration=String(loaded.record.firebaseIdentityGeneration||'');
  if(expectedGeneration&&expectedGeneration!==generation)fail(409,'SECURITY_IDENTITY_GENERATION_STALE','This Firebase identity request belongs to an older credential generation. Sign in again.');
  const expectedIdentityKey=await sha256HexServer([
    'trinotime-workforce-identity-v1',
    role,
    normalizePersonName(loaded.record.firebaseIdentityName||name).toLowerCase().replace(/\s+/g,' '),
    generation
  ].join('|'));
  const expectedEmail=`tt-${expectedIdentityKey.slice(0,40)}@identity.trinotime.invalid`;
  if(identityKey!==expectedIdentityKey)fail(403,'SECURITY_IDENTITY_KEY_MISMATCH','This Firebase identity does not match the active TrinoTime credential generation.');
  if(String(user.email||'').trim().toLowerCase()!==expectedEmail)fail(403,'SECURITY_IDENTITY_EMAIL_MISMATCH','This Firebase identity does not match the active TrinoTime workforce account.');

  // RC44 continuity handoff: a password-change/reprovision generation may replace
  // an already-approved Firebase UID. Because the Worker security session was just
  // verified against the current TrinoTime password, transfer the role only when
  // the credential itself names the same previous UID and that previous UID is
  // still active for the exact same worker and POD. Initial identity migrations
  // still require Admin review because they have no verified previous UID chain.
