  const scopeMode=cleanText(url.searchParams.get('scope')||'',40); if(scopeMode && scopeMode!=='home_pod') fail(400,'ATTENDANCE_SCOPE_MODE_INVALID','Choose a valid Attendance snapshot scope.');
  const homePodScope=scopeMode==='home_pod';
