    if(currentRaw===null){const legacyRaw=await firebaseAdminGet(env,`kv/${fbEncodeKeyServer(parsedKey.key)}`).catch(()=>null);if(legacyRaw!==null&&legacyRaw!==undefined){currentRaw=String(legacyRaw);bootstrapSource='legacy-kv';}}
