    const write=await firebaseAdminSetIfMatch(env,securePath,payload,current.etag); if(write.preconditionFailed)continue;
    const readBack=await firebaseAdminGet(env,securePath); if(String(readBack??'')!==payload) fail(503,'ATTENDANCE_READBACK_FAILED','The secure attendance write could not be verified.');
    const sideEffects=await attendancePostCommitSideEffectsServer(env,{parsedKey,record,payload,actor,authorization,forceLogoutIntent,metaPatch:{verified:true,tombstone:false,verifiedAt:safeIso(),lastWriteMutationId:mutationId,lastComparison:'write-verified',reconciliationRequired:false,secureRevision:localRevision,authorizedPod:authorization.targetPod}});
