    let metadataConfirmed=false,warnings=[];try{await writeAttendanceMetaServer(env,parsedKey.key,{verified:true,tombstone:true,verifiedAt:safeIso(),lastWriteMutationId:deleteToken,lastComparison:'secure-tombstone',reconciliationRequired:false,secureRevision:baseRevision+1,authorizedPod:authorization.targetPod});metadataConfirmed=true;}catch(error){warnings.push({stage:'attendance-meta',code:String(error?.code||'ATTENDANCE_META_PROJECTION_FAILED')});}
