function parseOvertimeLockKeyServer(key) {
  const raw=String(key||''),prefix='otpayrolllock:'; if(!raw.startsWith(prefix))return null;
  const periodStart=raw.slice(prefix.length); if(!parseAttendanceDatePartsServer(periodStart))return null;
  return {key:raw,periodStart};
}
function secureOvertimePathServer(key){return `${WORKFORCE_OVERTIME_ROOT}/${fbEncodeKeyServer(key)}`;}
function secureOvertimeMetaPathServer(key){return `${WORKFORCE_OVERTIME_META_ROOT}/${fbEncodeKeyServer(key)}`;}
