function overtimeRosterMatchesServer(roster,name){const target=normalizePersonName(name).toLowerCase();return Object.values(roster?.entries&&typeof roster.entries==='object'?roster.entries:{}).filter(x=>x&&x.active!==false&&normalizePersonName(x.name).toLowerCase()===target&&['agent','team_leader'].includes(credentialRole(x.role)));}
