    const selfSubmit=nextStatus==='pending'&&(oldStatus===''||['pending','withdrawn','rejected','revoked'].includes(oldStatus));
    const selfWithdraw=nextStatus==='withdrawn'&&oldStatus==='pending';
    if(!selfSubmit&&!selfWithdraw)fail(403,'OVERTIME_TL_TRANSITION_FORBIDDEN','Team Leaders may only submit or withdraw their own overtime request.');
    const submittedBy=normalizePersonName(nextRecord?.submittedBy||actor.name); if(nextStatus==='pending'&&submittedBy.toLowerCase()!==normalizePersonName(actor.name).toLowerCase())fail(403,'OVERTIME_TL_ACTOR_MISMATCH','The overtime request submitter does not match the authenticated Team Leader.');
    for(const field of ['approvedBy','approvedById','approvedAt','rejectedBy','rejectedById','rejectedAt','reviewedBy','reviewedById','reviewedAt','correctedBy','correctedById','correctedAt','revokedBy','revokedById','revokedAt'])if(nextRecord&&nextRecord[field]&&String(nextRecord[field])!==String(currentRecord&&currentRecord[field]||''))fail(403,'OVERTIME_TL_PRIVILEGED_FIELDS_FORBIDDEN','Team Leader self-service cannot set Admin review fields.');
    return {allowed:true,scope:'self-team-leader',...ctx};
