function scheduleRecordBackfillClassificationServer(secureRaw,legacyRaw){if(legacyRaw===null)return 'missing-legacy';const legacy=parseJsonString(legacyRaw,null);if(!legacy)return 'legacy-invalid';if(secureRaw===null)return 'missing-secure';const secure=parseJsonString(secureRaw,null);if(!secure)return 'secure-invalid';if(secureRaw===legacyRaw)return 'match';const sr=scheduleRecordRevisionServer(secure),lr=scheduleRecordRevisionServer(legacy);if(sr>lr)return 'secure-newer';if(lr>sr)return 'legacy-newer';return 'same-revision-payload-mismatch';}
