// Independent QA: personnel can maintain only THEIR OWN recurring days off.
// Changes are forward-effective from tomorrow Manila time, so earlier attendance
// and historical off-day determinations remain unchanged. No Team Leader route.
function qaDayOffEffectiveDaysServer(history,date){
  const list=Array.isArray(history)?history:[];
  for(let i=list.length-1;i>=0;i--)if(list[i]&&list[i].effectiveFrom<=date)return list[i].days;
  return null;
}
// The shared attendance date helper uses M/D/YYYY. QA history uses ISO YYYY-MM-DD.
// Never pass the attendance date directly to Date.parse: on Workers this creates
// an invalid date and turns the QA self-dayoff GET into an HTTP 500.
function qaManilaIsoDateServer(now=Date.now()){
  const parts=parseAttendanceDatePartsServer(manilaDateKeyServer(now));
  if(!parts)fail(503,'QA_DAYOFF_DATE_UNAVAILABLE','The trusted Philippine reporting date is unavailable.');
  return `${parts.y}-${String(parts.m).padStart(2,'0')}-${String(parts.d).padStart(2,'0')}`;
}
function qaNextManilaDateServer(now=Date.now()){
  const parts=leaveIsoPartsServer(qaManilaIsoDateServer(now));
  if(!parts)fail(503,'QA_DAYOFF_DATE_UNAVAILABLE','The next Philippine day could not be verified.');
  const next=new Date(Date.UTC(parts.y,parts.m-1,parts.d+1));
  return next.toISOString().slice(0,10);
}
async function qaSelfDayOffActorServer(request,env){
  const actor=await requireWorkforceAttendanceActor(request,env);
  if(actor.role!=='agent'||actor.pod!==OOS_QA_INDEPENDENT_POD)fail(403,'QA_SELF_SCHEDULE_ONLY','Only a signed-in independent QA may edit their own days off.');
  const roster=await rosterResolvedStateServer(env);
  const team=getOosCoverageBetaQasForActor(roster,actor);
  const member=(roster.employees?.entries||[]).filter(e=>e&&e.active!==false&&e.pod===OOS_QA_INDEPENDENT_POD&&normalizePersonName(e.name).toLowerCase()===normalizePersonName(actor.name).toLowerCase());
  if(roster.employees?.verified!==true||!team||team.scope!=='self-only'||member.length!==1)fail(403,'QA_SELF_IDENTITY_NOT_VERIFIED','QA roster identity could not be verified.');
  const employeeId=cleanText(member[0].employeeId||member[0].id||'',100);
  if(!/^[a-zA-Z0-9_-]{6,100}$/.test(employeeId))fail(409,'QA_SELF_ID_REQUIRED','Your verified internal employee ID is required.');
  return {actor,employeeId};
}
async function handleQaSelfDayOffServer(request,env){
  const {actor,employeeId}=await qaSelfDayOffActorServer(request,env);
  const date=qaManilaIsoDateServer(),effectiveFrom=qaNextManilaDateServer();
  if(request.method==='GET'){
    const state=await readScheduleBlobStateServer(env,'dayoff_schedule');
    const data=parseJsonString(state.payload||'{}',{}),pod=data?.[OOS_QA_INDEPENDENT_POD]||{};
    const list=pod?.qaSelfDayOffHistoryByEmployeeId?.[employeeId]||[];
    return {ok:true,team:OOS_QA_INDEPENDENT_POD,name:actor.name,days:qaDayOffEffectiveDaysServer(list,date)||[],pendingDays:qaDayOffEffectiveDaysServer(list,effectiveFrom),effectiveFrom,version:state.version,authority:'qa-self-dayoff-v1'};
  }
  if(request.method!=='POST')fail(405,'METHOD_NOT_ALLOWED','Use GET or POST.');
  const body=await parseBody(request);
  const days=body?.days,expectedVersion=String(body?.baseVersion||'');
  if(body?.confirm!=='SAVE_MY_QA_DAY_OFF'||!Array.isArray(days)||days.length>7||days.some(d=>!Number.isInteger(d)||d<0||d>6)||new Set(days).size!==days.length)fail(400,'QA_SELF_DAYOFF_INVALID','Confirm your own valid weekday selection.');
  const chosen=days.slice().sort((a,b)=>a-b),path=secureScheduleBlobPathServer('dayoff_schedule');
  for(let attempt=0;attempt<3;attempt++){
    const current=await firebaseAdminGetWithEtag(env,path);
    const stored=current.value&&typeof current.value==='object'&&typeof current.value.payload==='string'?current.value:null;
    // Require the existing authoritative secure schedule. Never silently bootstrap
    // an empty schedule or overwrite legacy data during a personnel self edit.
    if(!stored||!current.etag)fail(409,'QA_SELF_DAYOFF_SECURE_SCHEDULE_REQUIRED','An Admin must verify the secure day-off schedule before QA self edits.');
    if(String(stored.version||'')!==expectedVersion)fail(409,'QA_SELF_DAYOFF_VERSION_CHANGED','Schedule changed. Reopen the editor and review the latest version.');
    const parsed=parseJsonString(stored.payload,null);
    if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))fail(503,'QA_SELF_DAYOFF_CORRUPT','Schedule is not safely readable.');
    const before=parsed[OOS_QA_INDEPENDENT_POD]&&typeof parsed[OOS_QA_INDEPENDENT_POD]==='object'?parsed[OOS_QA_INDEPENDENT_POD]:{effective:'',rows:[['','','','','','','']],teamLeaderBackupByName:{}};
    const history=before.qaSelfDayOffHistoryByEmployeeId&&typeof before.qaSelfDayOffHistoryByEmployeeId==='object'?before.qaSelfDayOffHistoryByEmployeeId:{};
    const versions=Array.isArray(history[employeeId])?history[employeeId]:[];
    if(versions.length>=64)fail(409,'QA_SELF_DAYOFF_HISTORY_FULL','Ask Admin to archive historical schedule versions before further changes.');
    if(versions.some(v=>v.effectiveFrom>=effectiveFrom))fail(409,'QA_SELF_DAYOFF_ALREADY_PENDING','A schedule revision is already pending. Review it with Admin rather than overwriting it.');
    const revised={...parsed,[OOS_QA_INDEPENDENT_POD]:{...before,qaSelfDayOffHistoryByEmployeeId:{...history,[employeeId]:[...versions,{effectiveFrom,days:chosen,name:actor.name}]}}};
    validateScheduleDayOffBlobServer(revised);
    const payload=JSON.stringify(revised),version=`qa-dayoff-${Date.now().toString(36)}-${crypto.randomUUID()}`;
    const result=await firebaseAdminSetIfMatch(env,path,{payload,version},current.etag);
    if(result.preconditionFailed)fail(409,'QA_SELF_DAYOFF_CONFLICT','Schedule was updated concurrently. Reopen the editor.');
    const confirmed=await firebaseAdminGet(env,path);
    if(String(confirmed?.payload||'')!==payload||String(confirmed?.version||'')!==version)fail(503,'QA_SELF_DAYOFF_READBACK_FAILED','Schedule save could not be confirmed. Do not retry blindly.');
    const postCommit=await scheduleBlobPostCommitServer(env,'dayoff_schedule',payload,version,{verified:true,verifiedAt:safeIso(),lastVersion:version,authorizedScope:'qa-self-only',authorizedUid:actor.uid,authorizedName:actor.name,authorizedEmployeeId:employeeId,reconciliationRequired:false},{mirrorLegacy:true,previousPayload:parsed});
    return {ok:true,saved:true,name:actor.name,days:chosen,effectiveFrom,version,rosterUntouched:true,...postCommit,authority:'qa-self-dayoff-v1'};
  }
  fail(409,'QA_SELF_DAYOFF_CONFLICT','Schedule was updated. Reopen the editor.');
}

async function handleWorkforceScheduleApi(request,env,url){if(request.method==='OPTIONS')return new Response(null,{status:204});if(url.pathname==='/api/workforce/schedule/qa-self-dayoff'&&['GET','POST'].includes(request.method))return json(await handleQaSelfDayOffServer(request,env),200,{'Cache-Control':'no-store'});if(url.pathname==='/api/workforce/schedule/snapshot'&&request.method==='GET'){const actor=await requireWorkforceAttendanceActor(request,env);return json({ok:true,...await collectResolvedScheduleServer(env,actor),authority:'workforce-schedule-v1'});}if(url.pathname==='/api/workforce/schedule/record'&&request.method==='GET')return json(await handleScheduleReadRecord(request,env,url));if(url.pathname==='/api/workforce/schedule/transaction'&&request.method==='POST')return json(await handleScheduleRecordTransaction(request,env));if(url.pathname==='/api/workforce/schedule/delete'&&request.method==='POST')return json(await handleScheduleRecordDelete(request,env));if(url.pathname==='/api/workforce/schedule/blob'&&request.method==='POST')return json(await handleScheduleBlobTransaction(request,env));if(url.pathname==='/api/workforce/schedule/migration/backfill'&&request.method==='POST')return json(await handleScheduleBackfill(request,env));if(url.pathname==='/api/workforce/schedule/migration/compare'&&request.method==='GET')return json(await handleScheduleCompare(request,env));if(url.pathname==='/api/workforce/schedule/migration/status'&&request.method==='GET'){await requireActiveAdminUser(request,env);return json({ok:true,policy:await scheduleMigrationPolicyServer(env),migrationVersion:WORKFORCE_SCHEDULE_MIGRATION_VERSION});}if(url.pathname==='/api/workforce/schedule/migration/rollback'&&request.method==='POST'){const {user}=await requireActiveAdminUser(request,env),body=await parseBody(request),reason=cleanText(body.reason||'',500);if(!reason)fail(400,'SCHEDULE_ROLLBACK_REASON_REQUIRED','Enter a schedule rollback reason.');return json({ok:true,policy:await writeScheduleMigrationPolicyServer(env,{mode:'legacy-read-first',secureReadsEnabled:false,allowLegacyFallback:true,mirrorLegacyWrites:true,rollbackAt:safeIso(),rollbackByUid:user.uid,rollbackReason:reason})});}if(url.pathname==='/api/workforce/schedule/migration/resume-secure-reads'&&request.method==='POST'){const {user}=await requireActiveAdminUser(request,env),body=await parseBody(request);if(String(body.confirm||'')!=='SECURE_SCHEDULE_READS')fail(400,'SCHEDULE_RESUME_CONFIRM_REQUIRED','Secure schedule read confirmation is required.');return json({ok:true,policy:await writeScheduleMigrationPolicyServer(env,{mode:'secure-read-first',secureReadsEnabled:true,allowLegacyFallback:true,mirrorLegacyWrites:true,resumedAt:safeIso(),resumedByUid:user.uid})});}fail(404,'WORKFORCE_SCHEDULE_ENDPOINT_NOT_FOUND','Schedule authority endpoint not found.');}
// Workforce Authorization Phase 2C3A — server-authoritative Leave request + V2 entitlement policy boundary.
function parseLeaveStorageKeyServer(key) {
  const raw=String(key||''); if(!raw.startsWith('leave:'))return null;
  const id=cleanText(raw.slice(6),180); return id?{key:raw,id}:null;
}
function secureLeaveRequestPathServer(key){return `${WORKFORCE_LEAVE_REQUEST_ROOT}/${fbEncodeKeyServer(key)}`;}
function secureLeaveRequestMetaPathServer(key){return `${WORKFORCE_LEAVE_REQUEST_META_ROOT}/${fbEncodeKeyServer(key)}`;}
function leaveRevisionServer(record){const n=Number(record?._rev);return Number.isInteger(n)&&n>=0?n:0;}
function leaveRecordHasAuthorityEvidenceServer(record){return leaveRevisionServer(record)>0&&Boolean(cleanText(record?._mutationId||'',180));}
function leaveStatusServer(value){const s=normalizeStatusServer(value);return ['PENDING','APPROVED','REJECTED','WITHDRAWN','CANCELLED'].includes(s)?s:'';}
function leaveIsoPartsServer(value){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(value||'').trim());if(!m)return null;const y=Number(m[1]),mo=Number(m[2]),d=Number(m[3]),dt=new Date(Date.UTC(y,mo-1,d));if(dt.getUTCFullYear()!==y||dt.getUTCMonth()!==mo-1||dt.getUTCDate()!==d)return null;return {y,m:mo,d,comparable:y*10000+mo*100+d,date:dt};}
function leaveIsoToMdyServer(value){const p=leaveIsoPartsServer(value);return p?`${p.m}/${p.d}/${p.y}`:'';}
function leaveRangeDaysServer(start,end){const a=leaveIsoPartsServer(start),b=leaveIsoPartsServer(end);if(!a||!b||b.comparable<a.comparable)return [];const out=[];for(let ms=a.date.getTime(),stop=b.date.getTime();ms<=stop&&out.length<=90;ms+=86400000){const d=new Date(ms);out.push(`${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`);}return out;}
function leaveRangesOverlapServer(aStart,aEnd,bStart,bEnd){const a1=leaveIsoPartsServer(aStart),a2=leaveIsoPartsServer(aEnd),b1=leaveIsoPartsServer(bStart),b2=leaveIsoPartsServer(bEnd);return Boolean(a1&&a2&&b1&&b2&&a1.comparable<=b2.comparable&&b1.comparable<=a2.comparable);}
function leaveStableServer(value){if(Array.isArray(value))return value.map(leaveStableServer);if(value&&typeof value==='object'){const out={};for(const k of Object.keys(value).sort())out[k]=leaveStableServer(value[k]);return out;}return value;}
function leaveDeepEqualServer(a,b){try{return JSON.stringify(leaveStableServer(a))===JSON.stringify(leaveStableServer(b));}catch(_){return false;}}
function leaveCoreIdentityServer(record){return {id:String(record?.id||''),agentName:normalizePersonName(record?.agentName||''),startDate:String(record?.startDate||''),endDate:String(record?.endDate||''),leaveType:cleanText(record?.leaveType||'',120),duration:cleanText(record?.duration||'FULL_DAY',40),partialStartTime:cleanText(record?.partialStartTime||'',10),partialEndTime:cleanText(record?.partialEndTime||'',10),reason:cleanText(record?.reason||'',1200)};}
async function leaveMigrationPolicyServer(env){const stored=await firebaseAdminGet(env,WORKFORCE_LEAVE_MIGRATION_PATH).catch(()=>null);return {version:WORKFORCE_LEAVE_MIGRATION_VERSION,mode:'secure-read-first',secureReadsEnabled:true,allowLegacyFallback:true,mirrorLegacyWrites:true,...((stored&&typeof stored==='object')?stored:{})};}
async function writeLeaveMigrationPolicyServer(env,patch){const previous=await leaveMigrationPolicyServer(env),next={...previous,...patch,version:WORKFORCE_LEAVE_MIGRATION_VERSION,release:RELEASE,updatedAt:safeIso()};await firebaseAdminSet(env,WORKFORCE_LEAVE_MIGRATION_PATH,next);const confirmed=await firebaseAdminGet(env,WORKFORCE_LEAVE_MIGRATION_PATH);if(!confirmed||Number(confirmed.version)!==WORKFORCE_LEAVE_MIGRATION_VERSION||String(confirmed.mode||'')!==String(next.mode||''))fail(503,'LEAVE_MIGRATION_STATE_FAILED','Leave migration state could not be confirmed.');return confirmed;}
