function normalizeLeavePolicyV2Server(value){const src=value&&typeof value==='object'?value:{},ent=src.entitlements&&typeof src.entitlements==='object'?src.entitlements:{},out={};for(const [k,v] of Object.entries(ent)){const name=cleanText(k,120);if(!name)continue;if(v===null||v===''){out[name]=null;continue;}const n=Number(v);if(!Number.isFinite(n)||n<0||n>365)fail(400,'LEAVE_POLICY_VALUE_INVALID','Leave entitlement values must be between 0 and 365 days.');out[name]=Math.round(n*4)/4;}return {entitlements:out,updatedAt:safeIso(),updatedBy:cleanText(src.updatedBy||'',160)};}
