async function handleWorkforceLeavePolicy(request,env){if(request.method==='GET'){await requireWorkforceAttendanceActor(request,env);const state=await readLeavePolicyV2StateServer(env);return {ok:true,...state,authority:'workforce-leave-v1'};}const {user}=await requireActiveAdminUser(request,env),body=await parseBody(request),next=normalizeLeavePolicyV2Server(body.policy||body);next.updatedBy=normalizePersonName((await firebaseAdminGet(env,`roles/${user.uid}`).catch(()=>null))?.name||user.name||'Admin')||'Admin';await firebaseAdminSet(env,WORKFORCE_LEAVE_POLICY_V2_PATH,next);const readBack=await firebaseAdminGet(env,WORKFORCE_LEAVE_POLICY_V2_PATH);if(!leaveDeepEqualServer(readBack,next))fail(503,'LEAVE_POLICY_READBACK_FAILED','The secure Leave policy could not be verified.');await firebaseAdminSet(env,WORKFORCE_LEAVE_POLICY_V2_META_PATH,{verified:true,verifiedAt:safeIso(),migrationVersion:WORKFORCE_LEAVE_MIGRATION_VERSION,release:RELEASE,updatedByUid:user.uid});const migration=await leaveMigrationPolicyServer(env);let legacyMirrored=false;if(migration.mirrorLegacyWrites!==false){await firebaseAdminSet(env,`kv/${fbEncodeKeyServer('leave_policy_v2')}`,JSON.stringify(next));legacyMirrored=true;}return {ok:true,policy:next,source:'secure',legacyMirrored,authority:'workforce-leave-v1'};}
function leaveBackfillClassificationServer(secureRaw,legacyRaw){const s=secureRaw?parseJsonString(secureRaw,null):null,l=legacyRaw?parseJsonString(legacyRaw,null):null;if(legacyRaw&&!l)return 'legacy-invalid';if(secureRaw&&!s)return 'secure-invalid';if(!secureRaw&&legacyRaw)return 'missing-secure';if(secureRaw&&!legacyRaw)return 'secure-only';if(!secureRaw&&!legacyRaw)return 'empty';const sr=leaveRevisionServer(s),lr=leaveRevisionServer(l);if(sr>lr)return 'secure-newer';if(lr>sr)return 'legacy-newer';if(leaveDeepEqualServer(s,l))return 'match';if(String(s?._mutationId||'')&&String(s?._mutationId||'')===String(l?._mutationId||''))return 'mutation-payload-mismatch';return 'payload-mismatch';}
