// Phase 2C3B — server-authoritative HR Leave ledger, policy history, and employment profiles.
function leaveHrAgentIdServer(name){return encodeURIComponent(normalizePersonName(name).toLowerCase()).replace(/\./g,'%2E');}
function leaveHrEncodedPathServer(root,id){return `${root}/${fbEncodeKeyServer(String(id||''))}`;}
function leaveHrRoundServer(value){const n=Number(value);return Number.isFinite(n)?Math.round(n*10000)/10000:0;}
function leaveHrIsoServer(value){const raw=String(value||'').slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(raw)?raw:'';}
function leaveHrDateServer(iso){const p=leaveIsoPartsServer(iso);return p?p.date:null;}
function leaveHrAddDaysServer(iso,days){const d=leaveHrDateServer(iso);if(!d)return '';d.setUTCDate(d.getUTCDate()+Number(days||0));return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;}
function leaveHrAddMonthsServer(iso,months){const d=leaveHrDateServer(iso);if(!d)return '';const day=d.getUTCDate();d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+Number(months||0));const last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();d.setUTCDate(Math.min(day,last));return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;}
function leaveHrYearServer(iso){return Number(String(iso||'').slice(0,4))||0;}
function leaveHrRevServer(value){const n=Number(value?._rev);return Number.isInteger(n)&&n>=0?n:0;}
function leaveHrDefaultTypePolicyServer(type){return {tracked:true,paid:type!=='Unpaid Leave',accrualMode:'MANUAL',annualEntitlement:null,accrualAmount:null,payPeriodDays:14,cap:null,carryoverCap:null,expirationMonths:null,reservePending:true,enforceBalance:false,allowNegative:false,eligibilityDays:0,prorateFirstYear:false};}
function normalizeLeaveHrTypePolicyServer(type,value){const src=value&&typeof value==='object'?value:{},out={...leaveHrDefaultTypePolicyServer(type),...src};out.tracked=out.tracked!==false;out.paid=type==='Unpaid Leave'?false:out.paid!==false;out.reservePending=out.reservePending!==false;out.enforceBalance=out.enforceBalance===true;out.allowNegative=out.allowNegative===true;out.prorateFirstYear=out.prorateFirstYear===true;const mode=String(out.accrualMode||'MANUAL').toUpperCase();out.accrualMode=['MANUAL','FRONT_LOADED','MONTHLY','PAY_PERIOD'].includes(mode)?mode:'MANUAL';for(const k of ['annualEntitlement','accrualAmount','cap','carryoverCap','expirationMonths']){const v=out[k];out[k]=v===''||v===null||v===undefined?null:(Number.isFinite(Number(v))?leaveHrRoundServer(Number(v)):null);}out.payPeriodDays=Math.max(1,Math.min(60,Number(out.payPeriodDays)||14));out.eligibilityDays=Math.max(0,Math.min(3650,Number(out.eligibilityDays)||0));return out;}
function normalizeLeaveHrPolicyServer(value){const src=value&&typeof value==='object'?value:{},out={version:3,effectiveDate:leaveHrIsoServer(src.effectiveDate)||null,lockedThrough:leaveHrIsoServer(src.lockedThrough)||null,holidays:[],types:{},updatedAt:String(src.updatedAt||''),updatedBy:normalizePersonName(src.updatedBy||''),policyVersionId:cleanText(src.policyVersionId||'',180),_rev:leaveHrRevServer(src),_mutationId:cleanText(src._mutationId||'',180)};out.holidays=[...new Set((Array.isArray(src.holidays)?src.holidays:[]).map(leaveHrIsoServer).filter(Boolean))].sort();for(const type of WORKFORCE_LEAVE_HR_TYPES)out.types[type]=normalizeLeaveHrTypePolicyServer(type,src.types?.[type]);return out;}
function normalizeLeaveHrProfileServer(value,ctx){const src=value&&typeof value==='object'?value:{},status=String(src.status||'ACTIVE').toUpperCase();if(!['ACTIVE','INACTIVE','TERMINATED'].includes(status))fail(400,'LEAVE_HR_PROFILE_STATUS_INVALID','Choose a valid employment status.');const hireDate=leaveHrIsoServer(src.hireDate)||null,eligibilityDate=leaveHrIsoServer(src.eligibilityDate)||null,terminationDate=leaveHrIsoServer(src.terminationDate)||null;if(hireDate&&eligibilityDate&&eligibilityDate<hireDate)fail(400,'LEAVE_HR_PROFILE_ELIGIBILITY_INVALID','Leave eligibility date cannot be before the hire date.');if(hireDate&&terminationDate&&terminationDate<hireDate)fail(400,'LEAVE_HR_PROFILE_TERMINATION_INVALID','Termination date cannot be before the hire date.');if(status==='TERMINATED'&&!terminationDate)fail(400,'LEAVE_HR_PROFILE_TERMINATION_REQUIRED','A terminated employee requires a termination date.');return {agentName:ctx.targetName,agentId:leaveHrAgentIdServer(ctx.targetName),pod:ctx.targetPod,role:ctx.targetRole,status,hireDate,eligibilityDate,terminationDate,updatedAt:safeIso(),updatedBy:'',_rev:leaveHrRevServer(src),_mutationId:cleanText(src._mutationId||'',180)};}
function normalizeLeaveHrLedgerEntryServer(value){if(!value||typeof value!=='object'||Array.isArray(value))fail(400,'LEAVE_HR_LEDGER_INVALID','Leave ledger entry is invalid.');const kind=String(value.kind||'').toUpperCase(),units=leaveHrRoundServer(value.units),effectiveDate=leaveHrIsoServer(value.effectiveDate),leaveType=cleanText(value.leaveType||'',120);if(!WORKFORCE_LEAVE_HR_ENTRY_KINDS.has(kind)||!Number.isFinite(Number(value.units))||units===0||!effectiveDate||!WORKFORCE_LEAVE_HR_TYPES.includes(leaveType))fail(400,'LEAVE_HR_LEDGER_FIELDS_INVALID','Leave ledger kind, units, type, and effective date are required.');return {...value,id:cleanText(value.id||'',220),agentName:normalizePersonName(value.agentName||''),agentId:cleanText(value.agentId||'',220),pod:cleanText(value.pod||'',80),leaveType,year:leaveHrYearServer(effectiveDate),effectiveDate,units,kind,memo:cleanText(value.memo||'',1000),sourceRequestId:cleanText(value.sourceRequestId||'',180),voidsEntryId:cleanText(value.voidsEntryId||'',220),immutable:true};}
async function leaveHrMigrationPolicyServer(env){const stored=await firebaseAdminGet(env,WORKFORCE_LEAVE_HR_MIGRATION_PATH).catch(()=>null);return {version:WORKFORCE_LEAVE_HR_MIGRATION_VERSION,mode:'secure-read-first',secureReadsEnabled:true,allowLegacyFallback:true,mirrorLegacyWrites:true,...((stored&&typeof stored==='object')?stored:{})};}
async function writeLeaveHrMigrationPolicyServer(env,patch){const previous=await leaveHrMigrationPolicyServer(env),next={...previous,...patch,version:WORKFORCE_LEAVE_HR_MIGRATION_VERSION,release:RELEASE,updatedAt:safeIso()};await firebaseAdminSet(env,WORKFORCE_LEAVE_HR_MIGRATION_PATH,next);const confirmed=await firebaseAdminGet(env,WORKFORCE_LEAVE_HR_MIGRATION_PATH);if(!confirmed||Number(confirmed.version)!==WORKFORCE_LEAVE_HR_MIGRATION_VERSION||String(confirmed.mode||'')!==String(next.mode||''))fail(503,'LEAVE_HR_MIGRATION_STATE_FAILED','HR Leave migration state could not be confirmed.');return confirmed;}
async function leaveHrContextByAgentIdServer(env,agentId,nameHint=''){const roster=await ensureLeaveRosterSnapshotServer(env,'leave-hr-authority');const matches=[];for(const member of Object.values(roster.entries||{})){if(!member||member.active===false)continue;const generated=leaveHrAgentIdServer(member.name);if(String(member.employeeId||'')===String(agentId||'')||generated===String(agentId||'')||(nameHint&&samePersonServer(member.name,nameHint)))matches.push(member);}if(matches.length!==1)fail(409,'LEAVE_HR_PROFILE_SCOPE_UNVERIFIED','The HR Leave identity is missing or ambiguous in the verified workforce roster.');const member=matches[0];return {roster,member,targetRole:credentialRole(member.role),targetPod:cleanText(member.pod||'',80),targetName:normalizePersonName(member.name),targetAgentId:leaveHrAgentIdServer(member.name)};}
async function leaveHrActorCanAccessPodServer(env,actor,pod,dateIso=''){if(actor.role==='admin')return true;if(actor.role!=='team_leader')return false;if(cleanText(actor.pod||'',80)===cleanText(pod||'',80))return true;const delegated=await delegatedTlScopeServer(env,actor,cleanText(pod||'',80),leaveIsoToMdyServer(dateIso||leaveHrIsoServer(safeIso()))||manilaDateKeyServer()).catch(()=>({active:false}));return delegated.active===true;}
async function leaveHrCanReadPersonServer(env,actor,ctx,dateIso=''){if(actor.role==='admin')return true;if(actor.role==='agent')return actor.role===ctx.targetRole&&samePersonServer(actor.name,ctx.targetName);if(actor.role==='team_leader'){if(samePersonServer(actor.name,ctx.targetName)&&ctx.targetRole==='team_leader')return true;return leaveHrActorCanAccessPodServer(env,actor,ctx.targetPod,dateIso);}return false;}
