async function leaveHrPreflightRequestTransitionServer(env,current,incoming){
  if(!current)return {checked:false,reason:'missing-current'};
  const from=leaveStatusServer(current.status),to=leaveStatusServer(incoming.status);
  if(from===to||!['APPROVED','CANCELLED'].includes(to))return {checked:false,reason:'transition-not-applicable'};
  const policy=(await leaveHrReadPolicyServer(env)).policy;
  if(to==='APPROVED'){
    const typePolicy=normalizeLeaveHrTypePolicyServer(current.leaveType,policy.types?.[current.leaveType]);
    const enforceAvailableBalance=typePolicy.enforceBalance===true&&typePolicy.allowNegative!==true;
    const enforceLockedPeriod=Boolean(policy.lockedThrough);
    // Base Leave approval must not depend on the HR accounting projection when neither
    // an enforced balance nor a locked HR period needs validation. Ledger posting remains
    // deterministic best-effort post-commit via settleLeavePostCommitServer().
    if(!enforceAvailableBalance&&!enforceLockedPeriod)return {checked:false,reason:'no-enforced-hr-gate'};
    const entries=enforceAvailableBalance?await leaveHrAllLedgerServer(env):[];
    const ctx=await leaveContextServer(env,current.agentName,current.requesterRole),agentId=leaveHrAgentIdServer(ctx.targetName),startYear=leaveHrYearServer(current.startDate),endYear=leaveHrYearServer(current.endDate);
    for(let year=startYear;year<=endYear;year++){
      const units=await leaveHrRequestUnitsForYearServer(env,current,year);if(!(units>0))continue;
      if(enforceLockedPeriod){const effective=await leaveHrUsageEffectiveDateServer(env,current,year);if(policy.lockedThrough&&effective<=policy.lockedThrough)fail(409,'LEAVE_HR_PERIOD_LOCKED',`This leave would post into an HR period locked through ${policy.lockedThrough}.`);}
      if(enforceAvailableBalance){const posted=leaveHrEntryBalanceServer(entries,agentId,current.leaveType,year),reserved=typePolicy.reservePending?await leaveHrPendingReservationServer(env,ctx.targetName,current.leaveType,year,current.id):0,available=leaveHrRoundServer(posted-reserved);if(available<units)fail(409,'LEAVE_HR_BALANCE_INSUFFICIENT','This approval would exceed the authoritative available Leave balance.',{available,required:units,year});}
    }
    return {checked:true,enforceAvailableBalance,enforceLockedPeriod};
  }
  const entries=await leaveHrAllLedgerServer(env),usages=entries.filter(e=>e.kind==='LEAVE_USAGE'&&String(e.sourceRequestId||'')===String(current.id));
  for(const usage of usages){const already=entries.some(e=>e.kind==='LEAVE_REVERSAL'&&String(e.voidsEntryId||'')===String(usage.id));if(!already&&policy.lockedThrough&&usage.effectiveDate<=policy.lockedThrough)fail(409,'LEAVE_HR_PERIOD_LOCKED',`This Leave usage is in an HR period locked through ${policy.lockedThrough}.`);}
  return {checked:true};
}
