  // must never be used as an account name or authorization credential.
  const state=await rosterResolvedStateServer(env);
  if(!state.employees?.verified)fail(409,'PROFILE_DISPLAY_ROSTER_UNVERIFIED','The canonical employee roster must be verified before editing names.');
  const matches=(state.employees.entries||[]).filter(e=>e&&e.active!==false&&normalizePersonName(e.name).toLowerCase()===oldName.toLowerCase()&&String(e.pod||'')===pod);
