    // Existing projection path makes Admin, roster and Attendance display the
    // same label. If a mirror fails, stable mutationId supports safe retry.
    await writeProfileMetaServer(env,'agent',actor.name,{verified:true,verifiedAt:now,source:'admin-display-name',authorizedPod:pod,lastRevision:next._rev,lastMutationId:mutationId});
