  const pods={},teamLeaders={},sourcePods=parsed.pods&&typeof parsed.pods==='object'&&!Array.isArray(parsed.pods)?parsed.pods:{},sourceTls=parsed.teamLeaders&&typeof parsed.teamLeaders==='object'&&!Array.isArray(parsed.teamLeaders)?parsed.teamLeaders:{};
