function personnelCoachingSlugServer(value){return cleanText(value||'',200).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)||'unknown';}
function personnelCoachingPathServer(id){return `${WORKFORCE_PERSONNEL_COACHING_ROOT}/${fbEncodeKeyServer(id)}`;}
