function personnelLegacyCoachingLockKeyServer(kind,name){return `coachlock:${kind}:${personnelCoachingSlugServer(name)}`;}
function personnelCoachingStatusServer(v){return String(v||'').toUpperCase()==='COMPLETED'?'COMPLETED':'ACTIVE';}
function personnelCoachingTypeServer(v){const x=cleanText(v||'1-on-1',60);return WORKFORCE_PERSONNEL_COACHING_TYPES.has(x)?x:'Other';}
function personnelCoachingRevisionServer(rec){return Math.max(0,Number(rec?._rev)||0);}
