// RC46: fence an abandoned start before removing its advisory locks. The
// session-path ETag prevents a delayed request from committing after recovery.
async function personnelCoachingRecoverAbandonedLockServer(env,kind,name,expectedSessionId){
  const securePath=personnelCoachingLockPathServer(kind,name);
  const legacyPath=`kv/${fbEncodeKeyServer(personnelLegacyCoachingLockKeyServer(kind,name))}`;
  const [secure,legacy]=await Promise.all([firebaseAdminGetWithEtag(env,securePath),firebaseAdminGetWithEtag(env,legacyPath)]);
  const legacyLock=parseJsonString(String(legacy.value??''),null);
  const matching=[secure.value,legacyLock].filter(lock=>lock&&String(lock.sessionId||'')===expectedSessionId);
  if(!matching.length)return false;
  if(matching.some(lock=>!Number.isFinite(Number(lock.createdAtMs))||Number(lock.createdAtMs)<=0||Date.now()-Number(lock.createdAtMs)<120000))return false;
  const sessionPath=personnelCoachingPathServer(expectedSessionId);
  const legacySessionPath=`kv/${fbEncodeKeyServer('coaching:'+expectedSessionId)}`;
  const [session,legacySession]=await Promise.all([firebaseAdminGetWithEtag(env,sessionPath),firebaseAdminGet(env,legacySessionPath)]);
  const oldRecord=parseJsonString(String(legacySession??''),null);
  if(legacySession!==null&&legacySession!==undefined&&!oldRecord)return false;
  if(oldRecord && personnelCoachingStatusServer(oldRecord.status)!=='COMPLETED')return false;
  const doc=session.value;
  if(doc && !doc.abandonedStart){
    if(!personnelDocVerifiedServer(doc)||!doc.record||personnelCoachingStatusServer(doc.record.status)!=='COMPLETED')return false;
  }
  if(!doc){
    if(!session.etag)return false;
    const fenced=await firebaseAdminSetIfMatch(env,sessionPath,{abandonedStart:true,deleted:true,verified:false,sessionId:expectedSessionId,recoveredAt:safeIso(),release:RELEASE},session.etag);
    if(fenced.preconditionFailed)return false;
  }
  // Delete only the exact snapshots examined. Concurrent/new locks survive.
  for(const [path,snapshot,lock] of [[securePath,secure,secure.value],[legacyPath,legacy,legacyLock]]){
    if(lock&&String(lock.sessionId||'')===expectedSessionId){
      if(!snapshot.etag)return false;
      const removed=await firebaseAdminSetIfMatch(env,path,null,snapshot.etag);
      if(removed.preconditionFailed)return false;
    }
  }
  return true;
}
async function personnelCoachingAcquireLockServer(env,kind,name,sessionId){const path=personnelCoachingLockPathServer(kind,name),now=Date.now();for(let attempt=0;attempt<5;attempt++){const current=await firebaseAdminGetWithEtag(env,path),lock=current.value&&typeof current.value==='object'?current.value:null;if(lock&&String(lock.sessionId||'')===sessionId)return {ok:true,alreadyOwned:true,lock};if(lock&&Number(lock.expiresAtMs||0)>now){if(await personnelCoachingRecoverAbandonedLockServer(env,kind,name,String(lock.sessionId||'')))continue;return {ok:false,conflict:true,owner:String(lock.sessionId||'')};}if(!current.etag)fail(503,'COACHING_LOCK_ETAG_UNAVAILABLE','Coaching lock concurrency protection is unavailable.');const next={version:1,kind,name:normalizePersonName(name),sessionId,createdAtMs:now,expiresAtMs:now+WORKFORCE_PERSONNEL_COACHING_LOCK_TTL_MS,createdAt:safeIso(),release:RELEASE},write=await firebaseAdminSetIfMatch(env,path,next,current.etag);if(write.preconditionFailed)continue;const got=await firebaseAdminGet(env,path);if(!got||String(got.sessionId||'')!==sessionId)fail(503,'COACHING_LOCK_READBACK_FAILED','The secure coaching lock could not be verified.');await personnelMirrorCoachingLockServer(env,kind,name,next).catch(()=>false);return {ok:true,lock:got};}fail(409,'COACHING_LOCK_RETRY_REQUIRED','Coaching lock changed concurrently. Try again.');}
