function lifecycleAttendanceTombstoneServer(item,operationId,actor){const rec=item.record||{},rev=attendanceRecordRevisionServer(rec),noteOnly=lifecycleNoteOnlyAttendanceServer(rec);if(noteOnly)return JSON.stringify({...noteOnly,_rev:rev+1,_mutationId:`lifecycle:${operationId}:${item.encoded}`,_serverUpdatedAt:safeIso(),_lifecycleHistoryCleared:true});return JSON.stringify({_deleted:true,_rev:rev+1,_mutationId:`lifecycle:${operationId}:${item.encoded}`,_deletedAt:safeIso(),_deletedByUid:String(actor.uid||''),_deletedByRole:actor.role,_lifecycleOperationId:operationId});}
