async function chatRevokeSessionsServer(env,uid,operationId,revokedBefore,reason='permanent-agent-delete'){
  const targetUid=String(uid||'').trim();
  if(!targetUid)return {ok:true,skipped:true,uid:''};
  const lifecycle=String(reason||'').startsWith('permanent-agent-delete');
  const failureCode=lifecycle?'LIFECYCLE_CHAT_REVOCATION_FAILED':'SECURITY_CHAT_REVOCATION_FAILED';
  const failureMessage=lifecycle?'Permanent deletion was stopped because Messaging sessions could not be revoked safely. Try again.':'The security change was stopped because active Messaging sessions could not be revoked safely. Try again.';
  let response;
  try{response=await chatRealtimeStub(env).fetch('https://chat-realtime/session/revoke',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({uid:targetUid,revokedBefore,operationId,reason})});}
  catch(error){fail(503,failureCode,failureMessage,{cause:String(error?.message||error)});}
  const data=await response.json().catch(()=>({}));
  if(!response.ok||data?.ok!==true)fail(503,failureCode,failureMessage);
  return data;
}
async function lifecycleRevokeChatSessionsServer(env,target,operationId,revokedBefore){
  const uid=legacyChatUid('agent',target?.name||'',target?.employeeId||'',target?.pod||'');
  return chatRevokeSessionsServer(env,uid,operationId,revokedBefore,'permanent-agent-delete');
}

