// UX18P33: Admin bootstrap uses deadline-bounded, read-only Firebase lookups.
// An unreachable dependency must NEVER be interpreted as an absent Admin role.
// In particular, do not use .catch(()=>null) for this authority check.
async function adminBootstrapFirebaseReadServer(env,path,deadlineAt){
  const dbUrl=String(env.FIREBASE_DATABASE_URL||'').replace(/\/+$/,'');
  if(!/^https:\/\//i.test(dbUrl))fail(503,'ADMIN_BOOTSTRAP_CONFIG_UNAVAILABLE','Admin identity storage is not configured.');
  const remaining=()=>Math.max(0,Number(deadlineAt)-Date.now());
  if(remaining()<150)fail(503,'ADMIN_BOOTSTRAP_UPSTREAM_TIMEOUT','Admin identity verification is temporarily slow. Please retry.');
  let tokenTimer;
  let token;
  try{
    token=await Promise.race([
      getGoogleAccessToken(env),
      new Promise((_,reject)=>{tokenTimer=setTimeout(()=>reject(Object.assign(new Error('Admin token wait expired'),{code:'ADMIN_BOOTSTRAP_UPSTREAM_TIMEOUT'})),Math.min(4800,remaining()));})
    ]);
  }catch(error){
    if(error?.code==='ADMIN_BOOTSTRAP_UPSTREAM_TIMEOUT'||error?.code==='WORKFORCE_FIREBASE_AUTH_TIMEOUT')fail(503,'ADMIN_BOOTSTRAP_UPSTREAM_TIMEOUT','Admin identity verification is temporarily slow. Please retry.');
    if(Number(error?.status)===503)throw error;
    fail(503,'ADMIN_BOOTSTRAP_FIREBASE_UNAVAILABLE','Admin identity verification is temporarily unavailable. Please retry.');
  }finally{clearTimeout(tokenTimer);}
  if(remaining()<150)fail(503,'ADMIN_BOOTSTRAP_UPSTREAM_TIMEOUT','Admin identity verification is temporarily slow. Please retry.');
  const controller=new AbortController();
  const timer=setTimeout(()=>controller.abort(),Math.min(2800,remaining()));
  try{
    const response=await fetch(`${dbUrl}/${String(path||'').replace(/^\/+/, '')}.json`,{
      headers:{authorization:`Bearer ${token}`,accept:'application/json'},signal:controller.signal
    });
    if(!response.ok)fail(503,'ADMIN_BOOTSTRAP_FIREBASE_UNAVAILABLE','Admin identity storage did not respond successfully. Please retry.');
    return await response.json();
  }catch(error){
    if(controller.signal.aborted)fail(503,'ADMIN_BOOTSTRAP_UPSTREAM_TIMEOUT','Admin identity storage timed out. Please retry.');
    if(error?.status)throw error;
    fail(503,'ADMIN_BOOTSTRAP_FIREBASE_UNAVAILABLE','Admin identity storage is temporarily unavailable. Please retry.');
  }finally{clearTimeout(timer);}
}
