      if(viewerUid&&viewerIssuedAt>0&&!this._sessionAllowed(viewerUid,viewerIssuedAt))return Response.json({error:'CHAT_SESSION_REVOKED',message:'Workspace Messaging session was revoked. Sign in again if this account is still active.'},{status:401});
