    blurred: coverageSafeCountServer(source.blurred),
    deleted: coverageSafeCountServer(source.deleted),
    noMatch: coverageSafeCountServer(source.noMatch),
    productMatched: coverageSafeCountServer(source.productMatched),
    activeMs: coverageSafeMsServer(source.activeMs),
    idleMs: coverageSafeMsServer(source.idleMs),
    awayMs: coverageSafeMsServer(source.awayMs),
    awayTimingAvailable: coverageAwayTimingAvailableServer(source),
    elapsedMs: coverageSafeMsServer(source.elapsedMs),
    currentJob,
    currentTask: coverageSafeTaskIndexServer(source.currentTask),
    totalTasks: coverageSafeTaskIndexServer(source.totalTasks),
    pendingSubmission: source.pendingSubmission === true,
    trackerState,
    lastActivityAt,
    idleSinceAt,
    awaySinceAt,
    presenceUpdatedAt,
    idleThresholdMs: WORKFORCE_COVERAGE_IDLE_THRESHOLD_MS,
    extensionVersion: cleanText(source.extensionVersion || '', 32),
    clientSequence: Math.max(0, Math.floor(Number(source.clientSequence) || 0)),
