  const authoritativeSummary=await trackerShiftWorkflowSnapshotServer(env,'coverage',actor,shift);
  const clientSessionId=cleanText(body.shiftSessionId||'',80),clientGeneration=Math.max(0,Math.floor(Number(body.shiftGeneration)||0));
