  const summary = coverageSanitizeSummaryServer(body.summary);
  const dailyPath = `${WORKFORCE_COVERAGE_DAILY_PATH}/${date}/${actorKey}`;
  const previous = authoritativeSummary;
  if(previous?.recoveryPending)fail(409,'TRACKER_RECOVERY_PENDING','Finish shift recovery in the Tracker popup before syncing. Server counters are preserved.');
  const incomingSequence = Math.max(summary.clientSequence, Math.floor(Number(body.clientSequence) || 0));
  const sameShift=String(previous?.shiftSessionId||'')===shift.sessionId&&Number(previous?.shiftGeneration||0)===Number(shift.generation||0);
  const previousSequence = sameShift?Math.max(0, Number(previous?.clientSequence) || 0):0;
