function storeObservedV2Index(workflows,agents,roots){
  const pods=[...new Set(agents.map(a=>a.pod))];
  const result=new Map();
  for(let wi=0;wi<workflows.length;wi++)for(let pi=0;pi<pods.length;pi++){
    const type=workflows[wi],pod=pods[pi],root=roots[wi*pods.length+pi];
    const key=`${type}|${pod}`,byJob=new Map();
    for(const row of Object.values(root&&typeof root==='object'?root:{})){
      const jobId=coverageSafeJobIdServer(row?.jobId);
      if(!jobId||row.workflow!==type||row.pod!==pod||row.source!=='augmoto-job-row')continue;
      const name=storeObservedV2Name(row.storeName);
      if(!name)continue;
      byJob.set(jobId,{name,conflict:row.conflict===true});
    }
    result.set(key,byJob);
  }
  return result;
}
