  if(workflow==='coverage')coverageAssertExpectedViewerServer(request,actor);
  if(workflow==='confirmation')confirmationAssertExpectedViewerServer(request,actor);
  const role=coverageViewerRoleServer(actor.role);
  if(!role)fail(403,'STORE_INTEL_SCOPE_FORBIDDEN','Authorized workforce role required.');
  const expected=cleanText(request.headers.get('x-tt-metrics-expected-role')||'',40);
  if(workflow==='metrics'&&request.headers.has('x-tt-metrics-expected-role')&&expected!==role)fail(409,'STORE_INTEL_VIEWER_CHANGED','Metrics viewer identity changed.');
