  const workflows=workflow==='metrics'?['coverage','confirmation']:[workflow];
  const roots=await Promise.all(dates.flatMap(d=>workflows.map(type=>firebaseAdminGet(env,`${type==='coverage'?WORKFORCE_COVERAGE_JOB_PATH:WORKFORCE_CONFIRMATION_JOB_PATH}/${d}`).catch(()=>null))));
