async function handleWorkforceCoverageApi(request, env, url) {
  if (request.method === 'OPTIONS') return new Response(null,{status:204});
  const path = url.pathname.slice('/api/workforce/coverage'.length) || '/';
  if (path === '/bridge-token' && request.method === 'POST') return json(await coverageIssueBridgeServer(request,env));
  if (path === '/bridge-status' && request.method === 'GET') return json(await coverageBridgeStatusServer(request,env));
  if (path === '/recover-current-shift' && request.method === 'POST') return json(await trackerRecoverCurrentShiftServer(request,env,'coverage'));
  if (path === '/recover-ack' && request.method === 'POST') return json(await trackerRecoveryAcknowledgeServer(request,env,'coverage'));
  if (path === '/bridge-revoke-all' && request.method === 'POST') return json(await coverageRevokeBridgesServer(request,env));
  if (path === '/shift-state' && request.method === 'GET') return json(await coverageShiftStateServer(request,env));
  if (path === '/reset-current-shift' && request.method === 'POST') return json(await coverageResetCurrentShiftServer(request,env));
  if (path === '/sequence-resume-proof' && request.method === 'POST') return json(await trackerSequenceResumeProofServer(request,env,'coverage'));
  if (path === '/sync' && request.method === 'POST') return json(await coverageSyncServer(request,env));
  if (path === '/store-observations' && request.method === 'POST') return json(await storeObservedV2IngestServer(request,env,'coverage'));
  if (path === '/stores' && request.method === 'GET') return json(await storeIntelReportServer(request,env,url,'coverage'));
  if (path === '/dashboard' && request.method === 'GET') return json(await coverageDashboardServer(request,env,url));
  if (path === '/agent' && request.method === 'GET') return json(await coverageAgentDetailServer(request,env,url));
  fail(404,'WORKFORCE_COVERAGE_ENDPOINT_NOT_FOUND','Coverage authority endpoint not found.');
}
// ---- end Coverage Activity Tracker / Dashboard v1 -----------------------------

// ---- Store Assignment queue: POD-wide assignments with legacy Agent fallback -----
// The POD record is the shared work plan; individual legacy plans remain a fallback.
// Never infer actual store/job attribution from an assignment or selected filter.
const STORE_PLAN_ROOT='workforceStorePlans/v1/agentDates';
const STORE_PLAN_POD_ROOT='workforceStorePlans/v1/podDates';
function storePlanDbPathServer(date,name){
  const id=storePlanIdentityKey(name);
  if(!id)fail(400,'STORE_PLAN_AGENT_INVALID','Choose a valid Agent from the active workforce roster.');
  return `${STORE_PLAN_ROOT}/${date}/${fbEncodeKeyServer(id)}`;
}
function storePlanPodDbPathServer(date,pod){
  const id=String(pod||'').trim();
  if(!id||id.length>120)fail(400,'STORE_PLAN_POD_INVALID','Choose a valid active POD.');
  return `${STORE_PLAN_POD_ROOT}/${date}/${fbEncodeKeyServer('pod:'+id)}`;
}
async function storePlanManagerServer(request,env){
  const actor=await requireWorkforceAttendanceActor(request,env);
  if(!['admin','team_leader'].includes(actor.role))fail(403,'STORE_PLAN_MANAGER_REQUIRED','Only active Admins and authorized Team Leaders may manage store assignments.');
  if(actor.role==='team_leader'){
    const manager=await canonicalWorkforceMemberServer(env,'team_leader',actor.name,{force:true});
    if(!manager||manager.role!=='team_leader'||manager.active===false||!actor.pod||String(manager.pod)!==String(actor.pod))fail(403,'STORE_PLAN_MANAGER_POD_CHANGED','The Team Leader POD assignment changed. Sign in again.');
  }
  return actor;
}
async function storePlanTargetServer(env,actor,name){
  const agentName=normalizePersonName(name);
  if(!agentName||agentName.length>120)fail(400,'STORE_PLAN_AGENT_REQUIRED','Choose an active Agent.');
  const target=await canonicalWorkforceMemberServer(env,'agent',agentName,{force:true});
  if(!canManageStorePlan(actor,target))fail(403,'STORE_PLAN_SCOPE_FORBIDDEN','Agent is outside your authorized POD or not active.');
  return target;
}
async function storePlanPodListServer(env,actor){
  const roster=await canonicalWorkforceAuthorizationRosterServer(env,{force:true});
  const pods=new Map();
  for(const member of Object.values(roster.entries||{})){
    if(!canManageStorePlan(actor,member))continue;
    const pod=String(member.pod||'').trim();
    if(!pod||pod.length>120)continue;
    const item=pods.get(pod)||{pod,podLabel:String(member.podLabel||pod),agentsCount:0};
    item.agentsCount++;pods.set(pod,item);
  }
  // UI-only display metadata. Never use TL labels as authority keys.
  for(const member of Object.values(roster.entries||{})){
    if(member?.role!=='team_leader'||member.active===false)continue;
    const found=pods.get(String(member.pod||'').trim());
    if(found && (actor.role==='admin'||String(actor.pod)===found.pod) && !found.teamLeader)
      found.teamLeader=normalizePersonName(member.name);
  }
  return [...pods.values()].sort((a,b)=>a.podLabel.localeCompare(b.podLabel)||a.pod.localeCompare(b.pod));
}
async function storePlanPodTargetServer(env,actor,pod){
  const requested=String(pod||'').trim();
  if(!requested||requested.length>120)fail(400,'STORE_PLAN_POD_REQUIRED','Choose an active POD.');
  const target=(await storePlanPodListServer(env,actor)).find(x=>x.pod===requested);
  if(!target)fail(403,'STORE_PLAN_POD_SCOPE_FORBIDDEN','This POD has no active authorized Agents or is outside your access.');
  return target;
}
