// RC2 /instruction: chat-authenticated POD text notes. Separate from store dispatch,
// store assignments, Augmoto observations, attendance, and chat messages.
const POD_CHAT_INSTRUCTION_ROOT = 'workforceStorePlans/v1/podChatInstructions';
const POD_CHAT_INSTRUCTION_TTL_MS = 24 * 60 * 60 * 1000;
function podChatInstructionPathServer(pod) {
  const value = cleanText(pod || '', 120);
  if (!value) fail(400,'POD_INSTRUCTION_POD_REQUIRED','A verified POD is required.');
  return `${POD_CHAT_INSTRUCTION_ROOT}/${fbEncodeKeyServer('pod:' + value)}`;
}
function podChatInstructionViewServer(record,pod) {
  const valid=record?.schemaVersion===1 && String(record.pod)===String(pod) &&
    Number.isSafeInteger(record.revision) && record.revision >= 1;
  const active=Boolean(valid && record.active===true && String(record.text||'').trim() &&
    Number(record.expiresAtMs||0)>Date.now());
  return {ok:true,authority:'trinotime-pod-chat-instruction-v1',pod,
    active,revision:valid?record.revision:0,text:active?String(record.text):'',
    updatedAt:valid?record.updatedAt||null:null,
    updatedBy:valid?record.updatedByName||null:null,
    expiresAt:active?new Date(record.expiresAtMs).toISOString():null};
}
async function podChatInstructionChatServer(request,env,session,url) {
  const member=memberForUid(await readDirectory(env,true),String(session.uid||''));
  if(!member||member.active!==true||member.role!==session.role ||
     !['admin','team_leader'].includes(member.role))
    fail(403,'POD_INSTRUCTION_MANAGER_REQUIRED','Only a currently authorized Admin or Team Leader can publish POD instructions.');
  if(member.role==='team_leader') {
    const tl=await canonicalWorkforceMemberServer(env,'team_leader',member.name,{force:true});
    if(!tl||!tl.pod||String(tl.pod)!==String(member.pod)||String(session.pod)!==String(member.pod))
      fail(403,'POD_INSTRUCTION_POD_CHANGED','Your current Team Leader POD assignment cannot be verified. Sign in again.');
    const cred=await readAuthoritativeCredential(env,'team_leader',member.name,{migrateLegacy:false,skipActorCheck:true});
    if(!cred.record||cred.record.active===false ||
       (Number(cred.record.securitySessionsRevokedBefore||0)>0 && Number(session.iat||0)<=Number(cred.record.securitySessionsRevokedBefore)))
      fail(401,'POD_INSTRUCTION_SESSION_STALE','Your Team Leader session needs to be renewed.');
  }
  const body=request.method==='POST'?await parseBody(request):{};
  const conversationId=cleanText(request.method==='GET'?url.searchParams.get('conversationId'):body.conversationId,100);
  if(!conversationId)fail(400,'POD_INSTRUCTION_CONVERSATION_REQUIRED','Open the authorized POD chat first.');
  const {conversation}=await requireConversation(env,conversationId,session);
  if(conversation.type!=='team')fail(403,'POD_INSTRUCTION_TEAM_CHAT_ONLY','Publish POD instructions from a POD team chat, not from a DM or general chat.');
  const authorizedPods=await storePlanPodListServer(env,{role:member.role,name:member.name,pod:member.pod,uid:member.uid});
  const matches=authorizedPods.filter(p=>teamIdForPod(p.pod)===String(conversation.teamId||''));
  if(matches.length!==1 || (member.role==='team_leader' && matches[0].pod!==member.pod))
    fail(403,'POD_INSTRUCTION_SCOPE_UNVERIFIED','The selected POD chat cannot be uniquely matched to an authorized POD.');
  const pod=matches[0].pod,path=podChatInstructionPathServer(pod);
  if(request.method==='GET')return json(podChatInstructionViewServer(await firebaseAdminGet(env,path),pod),200,{'Cache-Control':'no-store'});
  if(request.method!=='POST')fail(405,'POD_INSTRUCTION_METHOD','Unsupported instruction command.');
  const action=String(body.action||'').toLowerCase();
  if(!['publish','clear'].includes(action))fail(400,'POD_INSTRUCTION_ACTION','Use /instruction [message] or /instruction clear.');
  const message=String(body.text||'').trim();
  if((action==='publish' && (!message||message.length>500||/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(message)))||
     (action==='clear' && message))fail(400,'POD_INSTRUCTION_TEXT','Enter an instruction of 1–500 characters without control characters.');
  if(!Number.isSafeInteger(body.expectedRevision)||body.expectedRevision<0)
    fail(400,'POD_INSTRUCTION_REVISION','Refresh instruction status before publishing.');
  enforceRate(session.uid,'pod-chat-instructions',15,10*60*1000);
  const {value:previous,etag}=await firebaseAdminGetWithEtag(env,path);
  if(!etag)fail(503,'POD_INSTRUCTION_ETAG','Concurrent update protection is unavailable.');
  if(previous && !(previous.schemaVersion===1 && String(previous.pod)===String(pod)))
    fail(409,'POD_INSTRUCTION_RECORD_CONFLICT','An unexpected POD instruction record exists.');
  const revision=Number(previous?.revision)||0;
  if(revision!==body.expectedRevision)fail(409,'POD_INSTRUCTION_CHANGED','Another Team Leader changed the instruction. Read /instruction status and try again.');
  const now=Date.now();
  const record={schemaVersion:1,pod,active:action==='publish',text:action==='publish'?message:'',revision:revision+1,
    updatedAt:new Date(now).toISOString(),updatedAtMs:now,
    updatedByUid:String(member.uid||''),updatedByName:member.name,updatedByRole:member.role,
    expiresAtMs:action==='publish'?now+POD_CHAT_INSTRUCTION_TTL_MS:now};
  const saved=await firebaseAdminSetIfMatch(env,path,record,etag);
  if(!saved.committed)fail(409,'POD_INSTRUCTION_CONCURRENT_WRITE','Another Team Leader updated the instruction. Retry from current status.');
  return json({...podChatInstructionViewServer(record,pod),saved:true},200,{'Cache-Control':'no-store'});
}
async function podChatInstructionMineServer(request,env) {
  const coverage=Boolean(request.headers.get('x-tt-coverage-bridge')),
        confirmation=Boolean(request.headers.get('x-tt-confirmation-bridge'));
  if(coverage===confirmation)fail(401,'POD_INSTRUCTION_BRIDGE_REQUIRED','Connect one authorized Tracker workflow.');
  const agent=coverage?await coverageRequireBridgeActorServer(request,env):
    await confirmationRequireBridgeActorServer(request,env);
  const pod=cleanText(agent.pod||'',120);
  if(!pod)fail(403,'POD_INSTRUCTION_AGENT_POD','Agent POD could not be verified.');
  return json(podChatInstructionViewServer(await firebaseAdminGet(env,podChatInstructionPathServer(pod)),pod),200,{'Cache-Control':'no-store'});
}
