async function handleWorkforceConfirmationApi(request, env, url) {
  if (request.method === 'OPTIONS') return new Response(null,{status:204});
  const path = url.pathname.slice('/api/workforce/confirmation'.length) || '/';
  if (path === '/bridge-token' && request.method === 'POST') return json(await confirmationIssueBridgeServer(request,env));
  if (path === '/bridge-status' && request.method === 'GET') return json(await confirmationBridgeStatusServer(request,env));
  if (path === '/recover-current-shift' && request.method === 'POST') return json(await trackerRecoverCurrentShiftServer(request,env,'confirmation'));
  if (path === '/recover-ack' && request.method === 'POST') return json(await trackerRecoveryAcknowledgeServer(request,env,'confirmation'));
  if (path === '/bridge-revoke-all' && request.method === 'POST') return json(await confirmationRevokeBridgesServer(request,env));
  if (path === '/shift-state' && request.method === 'GET') return json(await confirmationShiftStateServer(request,env));
  if (path === '/sequence-resume-proof' && request.method === 'POST') return json(await trackerSequenceResumeProofServer(request,env,'confirmation'));
  if (path === '/sync' && request.method === 'POST') return json(await confirmationSyncServer(request,env));
  if (path === '/store-observations' && request.method === 'POST') return json(await storeObservedV2IngestServer(request,env,'confirmation'));
  if (path === '/stores' && request.method === 'GET') return json(await storeIntelReportServer(request,env,url,'confirmation'));
  if (path === '/dashboard' && request.method === 'GET') return json(await confirmationDashboardServer(request,env,url));
  if (path === '/agent' && request.method === 'GET') return json(await confirmationAgentDetailServer(request,env,url));
  fail(404,'WORKFORCE_CONFIRMATION_ENDPOINT_NOT_FOUND','Confirmation authority endpoint not found.');
}
