async function deepChatHealth(request, env) {
  const session = await requireChatSession(request, env);
  if (session.role !== 'admin') fail(403, 'CHAT_ADMIN_REQUIRED', 'Only Admins can run infrastructure diagnostics.');
  const ip = cleanText(request.headers.get('cf-connecting-ip') || 'unknown', 80);
  enforceRate(`health:${ip}`, 'deep-health', 12, 10 * 60 * 1000);
  const tests = { firebaseServiceAccount:false, firebaseRolesRead:false, firebaseEmployeesRead:false, durableSql:false, directory:false };
  const codes = [];
  let roleCount = 0, employeeCount = 0, memberCount = 0;
  try { await getGoogleAccessToken(env); tests.firebaseServiceAccount = true; } catch (e) { codes.push(e?.code || 'CHAT_FIREBASE_ADMIN_AUTH_FAILED'); }
  if (tests.firebaseServiceAccount) {
    try { const roles = await firebaseAdminGet(env, 'roles'); roleCount = roles && typeof roles === 'object' ? Object.keys(roles).length : 0; tests.firebaseRolesRead = true; } catch (e) { codes.push(e?.code || 'CHAT_MEMBERSHIP_UNAVAILABLE'); }
    try { const rosterState = await rosterResolvedStateServer(env); const rows = rosterState?.employees?.entries || []; employeeCount = Array.isArray(rows) ? rows.length : 0; tests.firebaseEmployeesRead = true; tests.secureRosterAuthority = rosterState?.employees?.verified === true; } catch (e) { codes.push(e?.code || 'CHAT_MEMBERSHIP_UNAVAILABLE'); }
  }
  try { const stats = await chatStoreFetch(env, '/store/stats'); tests.durableSql = stats?.storage === 'durable-sqlite'; if (!tests.durableSql) codes.push('CHAT_STORAGE_NOT_READY'); } catch (e) { codes.push(e?.code || 'CHAT_STORAGE_ERROR'); }
  if (tests.firebaseRolesRead && tests.firebaseEmployeesRead && tests.durableSql) {
    try { const members = await readDirectory(env, true); memberCount = members.length; tests.directory = memberCount > 0; if (!tests.directory) codes.push('CHAT_DIRECTORY_EMPTY'); } catch (e) { codes.push(e?.code || 'CHAT_DIRECTORY_FAILED'); }
  }
  const ready = tests.firebaseServiceAccount && tests.firebaseRolesRead && tests.firebaseEmployeesRead && tests.durableSql && tests.directory;
  return json({ ok:ready, release:RELEASE, architecture:'durable-sqlite', deep:true, tests, counts:{ roles:roleCount, employees:employeeCount, members:memberCount }, diagnosticCodes:[...new Set(codes)].slice(0,8) }, ready ? 200 : 503);
}

